package com.gb.astralita.material;
import com.gb.astralita.AstralitaMod;import com.gb.astralita.registry.ModItems;import net.minecraft.sounds.*;import net.minecraft.world.item.*;import net.minecraft.world.item.crafting.Ingredient;
public class AstralitaArmorMaterial implements ArmorMaterial{public static final AstralitaArmorMaterial INSTANCE=new AstralitaArmorMaterial();public int getDurabilityForType(ArmorItem.Type t){return switch(t){case BOOTS->546;case LEGGINGS->630;case CHESTPLATE->672;case HELMET->462;};}public int getDefenseForType(ArmorItem.Type t){return switch(t){case BOOTS->4;case LEGGINGS->7;case CHESTPLATE->9;case HELMET->4;};}public int getEnchantmentValue(){return 18;}public SoundEvent getEquipSound(){return SoundEvents.ARMOR_EQUIP_NETHERITE;}public Ingredient getRepairIngredient(){return Ingredient.of(ModItems.BARRA_ASTRALITA.get());}public String getName(){return "minecraft:netherite";}public float getToughness(){return 4;}public float getKnockbackResistance(){return .15F;}}
